-- Code generated by factory from specs/sales/list-daily-sales-cost-rates/spec.yaml. DO NOT EDIT.

-- name: ListDailySalesCostRates :many
SELECT t6.sales_date, t6.amount, t6.cost_rate, t6.rate_from, t6.current_cost_rate
FROM (
    SELECT t1.sales_date AS sales_date, t1.amount AS amount, t3.cost_rate AS cost_rate, t3.valid_from AS rate_from, t5.cost_rate AS current_cost_rate
    FROM daily_sales AS t1
    LEFT JOIN LATERAL (
        SELECT t2.cost_rate, t2.valid_from
        FROM store_cost_rates AS t2
        WHERE t2.store_code = t1.store_code
          AND (t2.rate_kind = 'STD'::text)
          AND t2.valid_from <= t1.sales_date
          AND (t2.valid_to IS NULL OR t1.sales_date <= t2.valid_to)
        ORDER BY t2.valid_from DESC
        LIMIT 1
    ) AS t3 ON TRUE
    LEFT JOIN LATERAL (
        SELECT t4.cost_rate
        FROM store_cost_rates AS t4
        WHERE t4.store_code = t1.store_code
          AND (t4.rate_kind = 'STD'::text)
          AND t4.valid_from <= ((sqlc.arg(factory_now)::timestamptz AT TIME ZONE 'Asia/Tokyo')::date)
          AND (t4.valid_to IS NULL OR ((sqlc.arg(factory_now)::timestamptz AT TIME ZONE 'Asia/Tokyo')::date) <= t4.valid_to)
        ORDER BY t4.valid_from DESC
        LIMIT 1
    ) AS t5 ON TRUE
    WHERE (t1.store_code = sqlc.arg(store_code)::int4)
      AND (t1.sales_date >= sqlc.arg('from')::date)
      AND ((sqlc.narg('to')::date IS NULL) OR (t1.sales_date <= sqlc.narg('to')::date))
) AS t6
ORDER BY t6.sales_date
LIMIT 63;
